using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.ANM.LogVisualizacionAnuncios;using GraphApi.Services.ANM.LogVisualizacionAnuncios;namespace GraphApi.Controllers.ANM.LogVisualizacionAnuncios{    /// <summary>    /// Gestión de LogVisualizacionAnuncios: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("ANM/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre LogVisualizacionAnuncios")]    public class LogVisualizacionAnunciosController : Controller    {        private readonly ILogVisualizacionAnunciosService _objService;        public LogVisualizacionAnunciosController(ILogVisualizacionAnunciosService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los LogVisualizacionAnuncios, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="logVisualizacionAnuncioID">LogVisualizacionAnuncioID</param>        /// <param name="anuncioID">AnuncioID</param>        /// <param name="usuarioID">UsuarioID</param>        /// <param name="medio">Medio</param>        /// <param name="iPOrigen">IPOrigen</param>        /// <param name="userAgent">UserAgent</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de LogVisualizacionAnuncios</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar LogVisualizacionAnuncios",            Description = "Devuelve LogVisualizacionAnuncios aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadLogVisualizacionAnuncios>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadLogVisualizacionAnuncios>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? logVisualizacionAnuncioID,            [FromQuery] int? anuncioID,            [FromQuery] int? usuarioID,            [FromQuery] string? medio,            [FromQuery] string? iPOrigen,            [FromQuery] string? userAgent,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetLogVisualizacionAnunciosDynamic(                logVisualizacionAnuncioID,                 anuncioID,                 usuarioID,                 medio,                 iPOrigen,                 userAgent,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo LogVisualizacionAnuncio.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del LogVisualizacionAnuncio a crear.</param>        /// <returns>El LogVisualizacionAnuncio recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear LogVisualizacionAnuncios",            Description = "Inserta un nuevo LogVisualizacionAnuncio en la base de datos."        )]        [ProducesResponseType(typeof(clReadLogVisualizacionAnuncios), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadLogVisualizacionAnuncios>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateLogVisualizacionAnuncios objInput)        {            var vCreated = await _objService.CreateLogVisualizacionAnuncios(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de LogVisualizacionAnuncio.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del LogVisualizacionAnuncio.</param>        /// <returns>El LogVisualizacionAnuncio actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar LogVisualizacionAnuncios",            Description = "Actualiza uno o varios campos de LogVisualizacionAnuncio existente."        )]        [ProducesResponseType(typeof(clReadLogVisualizacionAnuncios), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadLogVisualizacionAnuncios>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateLogVisualizacionAnuncios objInput)        {            var vUpdated = await _objService.UpdateLogVisualizacionAnuncios(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un LogVisualizacionAnuncio por su ID.        /// </summary>        [HttpDelete("{nLogVisualizacionAnunciosID:int}")]        [SwaggerOperation(            Summary = "Eliminar LogVisualizacionAnuncio",            Description = "Borra un LogVisualizacionAnuncio si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nLogVisualizacionAnunciosID)        {            var success = await _objService.DeleteLogVisualizacionAnuncios(nLogVisualizacionAnunciosID);            return success ? NoContent() : NotFound();        }    }}